import type { ConversationEvent } from "../types";

export interface BargeInPlaybackView {
  /** Offset the playback provably reached (last acknowledged marker), if any. */
  confirmedThroughMs: number | undefined;
  /** Written reply word the user was hearing when they interrupted, if known. */
  interruptedWord: string | undefined;
  /** Zero-based position of `interruptedWord` in the written reply. */
  interruptedWordIndex: number | undefined;
  /** Number of words in the written reply. */
  responseWordCount: number | undefined;
  /** Full duration of the interrupted response audio, if known. */
  totalAudioDurationMs: number | undefined;
  markerCount: number;
}

export function formatDuration(milliseconds: number): string {
  return `${(milliseconds / 1000).toFixed(1)} s`;
}

/** Playback context of a barge-in event, shared by its log row and detail panel. */
export function bargeInPlayback(event: ConversationEvent): BargeInPlaybackView {
  const playback = event.metadata.playback;
  const markers = playback?.acknowledged_intermediate_markers ?? [];
  const lastMarker = markers.at(-1);
  return {
    confirmedThroughMs: lastMarker?.offset_ms,
    interruptedWord: playback?.interrupted_word,
    interruptedWordIndex: playback?.interrupted_word_index,
    responseWordCount: playback?.response_word_count,
    totalAudioDurationMs: playback?.total_audio_duration_ms,
    markerCount: markers.length,
  };
}
